mapper.select:
SELECT i.id, i.title, i.author, i.summary, i.views, i.likes, i.collects, i.publish_date AS `date`, c.code AS category, c.name AS categoryName, co.name AS companyName, co.avatar_text AS avatar, co.avatar_color AS avatarColor, GROUP_CONCAT(DISTINCT t.name ORDER BY t.id ASC SEPARATOR ',') AS tagsStr FROM interview i JOIN category c ON i.category_id = c.id JOIN company co ON i.company_id = co.id LEFT JOIN interview_tag it ON i.id = it.interview_id LEFT JOIN tag t ON it.tag_id = t.id WHERE i.status = 1
AND c.code = #{category}
AND ( EXISTS ( SELECT 1 FROM interview_tag fit JOIN tag ft ON fit.tag_id = ft.id WHERE fit.interview_id = i.id AND LOWER(ft.name) = LOWER(#{tag}) ) OR LOWER(IFNULL(i.tag_list, '')) LIKE CONCAT('%', LOWER(#{tag}), '%') )
AND (i.title LIKE CONCAT('%', #{keyword}, '%') OR i.author LIKE CONCAT('%', #{keyword}, '%') OR i.summary LIKE CONCAT('%', #{keyword}, '%'))
GROUP BY i.id, i.title, i.author, i.summary, i.views, i.likes, i.collects, i.publish_date, c.code, c.name, co.name, co.avatar_text, co.avatar_color ORDER BY i.publish_date DESC, i.likes DESC LIMIT #{pageSize} OFFSET #{offset}

SELECT id, likes, collects
FROM interview
WHERE id = #{id}

SELECT DISTINCT merged.tag_name FROM ( SELECT TRIM(SUBSTRING_INDEX(SUBSTRING_INDEX(i.tag_list, '|', seq.n), '|', -1)) AS tag_name FROM interview i JOIN category c ON i.category_id = c.id JOIN ( SELECT 1 AS n UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9 UNION ALL SELECT 10 UNION ALL SELECT 11 UNION ALL SELECT 12 UNION ALL SELECT 13 UNION ALL SELECT 14 UNION ALL SELECT 15 UNION ALL SELECT 16 UNION ALL SELECT 17 UNION ALL SELECT 18 UNION ALL SELECT 19 UNION ALL SELECT 20 ) seq ON i.tag_list IS NOT NULL AND i.tag_list != '' AND seq.n <= 1 + LENGTH(i.tag_list) - LENGTH(REPLACE(i.tag_list, '|', '')) WHERE i.status = 1
AND c.code = #{categoryCode}
UNION
SELECT t.name AS tag_name FROM interview i JOIN interview_tag it ON i.id = it.interview_id JOIN tag t ON it.tag_id = t.id JOIN category c ON i.category_id = c.id WHERE i.status = 1
AND c.code = #{categoryCode}
) merged WHERE merged.tag_name IS NOT NULL AND merged.tag_name != '' ORDER BY merged.tag_name ASC
